import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const appDirectory = resolve(scriptDirectory, "../outputs/kana-card");

function readSource(fileName) {
  return readFileSync(resolve(appDirectory, fileName), "utf8");
}

function removeImportStatements(source) {
  return source.replace(/^import\s+[\s\S]*?from\s+["'][^"']+["'];\s*/gm, "");
}

function removeExports(source) {
  return source.replace(/^export\s+/gm, "");
}

const kanaData = removeExports(readSource("kana-data.js"));
const learningEngine = removeExports(removeImportStatements(readSource("learning-engine.js")));
const application = removeImportStatements(readSource("app.js"));

const bundle = `/* Generated by work/build-classic-bundle.mjs. */
(() => {
  "use strict";

  ${kanaData}

  globalThis.KanaData = {
    ROWS,
    ALL_ROWS,
    KANA_DATA,
    KANA_BY_ID,
    LEARNING_STAGES,
    getCharacter,
    getRow,
    getScriptName,
    getStage,
    itemSupportsScript,
    getTotalStudyUnits
  };
})();

(() => {
  "use strict";

  const {
    ALL_ROWS,
    KANA_BY_ID,
    KANA_DATA,
    ROWS,
    getCharacter,
    getStage,
    itemSupportsScript
  } = globalThis.KanaData;
  ${learningEngine}

  globalThis.KanaEngine = {
    SESSION_LIMITS,
    scriptsForMode,
    progressKey,
    defaultRecord,
    getRecord,
    ensureRecord,
    getLearnedCount,
    getMasteredCount,
    getStageProgress,
    isStageUnlocked,
    getUnlockedStages,
    getDueItems,
    getMistakeItems,
    getReviewSummary,
    isHardRecord,
    getNewCandidates,
    getNextUnseenItems,
    getNextRow,
    getRowStats,
    buildSession,
    getCurrentCard,
    getSessionProgress,
    getExpectedAnswer,
    getChoices,
    applyAnswer,
    getPlan
  };
})();

(() => {
  "use strict";

  const {
    KANA_BY_ID,
    KANA_DATA,
    ROWS,
    ALL_ROWS,
    LEARNING_STAGES,
    getCharacter,
    getRow,
    getScriptName,
    getStage,
    getTotalStudyUnits
  } = globalThis.KanaData;
  const {
    SESSION_LIMITS,
    applyAnswer,
    buildSession,
    getChoices,
    getCurrentCard,
    getDueItems,
 getMistakeItems,
 getReviewSummary,
    getLearnedCount,
    getMasteredCount,
    getStageProgress,
    isStageUnlocked,
    getUnlockedStages,
    getPlan,
    getRecord,
    getRowStats,
    getSessionProgress,
    scriptsForMode
  } = globalThis.KanaEngine;

  ${application}
})();
`;

const outputPath = resolve(appDirectory, "app.bundle.js");
writeFileSync(outputPath, bundle);
console.log(`Generated ${outputPath}`);